CREATE FUNCTION public.network_public_service_centers() RETURNS TABLE(workspace_id uuid,lat double precision,lng double precision,radius_miles integer,city text,county text,zip text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT w.id,p.public_center_lat,p.public_center_lng,p.service_radius_miles,p.location_city,p.location_county,p.location_zip FROM workspaces w JOIN provider_network_profiles p ON p.workspace_id=w.id WHERE auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM user_profiles WHERE user_id=auth.uid() AND status='active' AND deleted_at IS NULL) AND w.status='active' AND w.account_type='provider' AND w.provider_verified AND NOT w.is_test_account AND p.visible $$;
REVOKE ALL ON FUNCTION public.network_public_service_centers() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.network_public_service_centers() TO authenticated;
CREATE FUNCTION public.validate_public_service_center() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF (NEW.public_center_lat IS NULL)<>(NEW.public_center_lng IS NULL) OR NEW.public_center_lat NOT BETWEEN -90 AND 90 OR NEW.public_center_lng NOT BETWEEN -180 AND 180 OR NEW.service_radius_miles<0 OR length(NEW.location_city)>100 OR length(NEW.location_county)>100 OR (NEW.location_zip IS NOT NULL AND NEW.location_zip !~ '^\d{5}$') THEN RAISE EXCEPTION 'Invalid public service center'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_public_service_center BEFORE INSERT OR UPDATE ON public.provider_network_profiles FOR EACH ROW EXECUTE FUNCTION public.validate_public_service_center();